CreateThread(function()
    Remove = {}
    if cityName == "CidadeNobre" then
        Remove = {"92","32"}
    end
    for i=1,#Remove do
        Robberys[tostring(Remove[i])] = nil
    end
end)

function GetAllRobberys()
    return Robberys
end
exports("GetAllRobberys", GetAllRobberys)

function GetTypeRobberys(robberyType)
    local RobberysSelected = {}
    robberyType = _t(robberyType)   
    for k,v in pairs(Robberys) do
        if v.type == robberyType then
            table.insert(RobberysSelected, v.Coords)
        end
    end
    return RobberysSelected or {}
end
exports("GetTypeRobberys", GetTypeRobberys)
